package main

// Adder is the narrow contract that callers depend on. Depending on this
// interface instead of a concrete implementation makes the helper easy to
// substitute in tests.
type Adder interface {
	Add(a, b int) int
}

// Calculator is the production implementation of Adder. Its zero value is
// ready to use.
type Calculator struct{}

// Add returns the sum of a and b.
func (Calculator) Add(a, b int) int {
	return a + b
}

// sum exercises the Adder seam. Receiving the dependency as an argument lets
// tests inject a fake instead of the real implementation.
func sum(adder Adder, a, b int) int {
	return adder.Add(a, b)
}

// add remains the public helper. It is a thin adapter over the new structure,
// so the existing API and tests keep working unchanged.
func add(a, b int) int {
	return sum(Calculator{}, a, b)
}

func main() {}

