package main

import "testing"

func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

type stubAdder struct {
	calls []struct{ a, b int }
	result int
}

func (s *stubAdder) Add(a, b int) int {
	s.calls = append(s.calls, struct{ a, b int }{a, b})
	return s.result
}

func TestCalculatorAdd(t *testing.T) {
	c := Calculator{}
	cases := []struct {
		a, b, want int
	}{
		{2, 3, 5},
		{-1, 1, 0},
		{0, 0, 0},
	}
	for _, tc := range cases {
		if got := c.Add(tc.a, tc.b); got != tc.want {
			t.Fatalf("Calculator.Add(%d, %d) = %d, want %d", tc.a, tc.b, got, tc.want)
		}
	}
}

func TestSumUsesInjectedAdder(t *testing.T) {
	stub := &stubAdder{result: 42}
	got := sum(stub, 7, 9)
	if got != 42 {
		t.Fatalf("sum = %d, want 42", got)
	}
	if len(stub.calls) != 1 || stub.calls[0].a != 7 || stub.calls[0].b != 9 {
		t.Fatalf("stub not called as expected: %+v", stub.calls)
	}
}

